const DIFF_BY_SOURCE: Record<string, Difficulty> = {
  'numple0.data': 'easy',
  'numple1.data': 'easy',
  'numple2.data': 'easy',
  'numple3.data': 'medium',
  'numple4.data': 'medium',
  'numple5.data': 'medium',
  'numple6.data': 'hard',
  'numple7.data': 'hard',
  'numple8.data': 'expert',
  'numple9.data': 'expert',
};

const parsedCache = new Map<string, NumplePuzzle>();

function build(id: string, cellsStr: string): NumplePuzzle {
  const cut = id.lastIndexOf('_');
  const source = id.slice(0, cut);
  const indexInFile = parseInt(id.slice(cut + 1), 10);
  const cells: Value[] = new Array(81);
  let countFilled = 0;
  for (let i = 0; i < 81; i++) {
    const v = cellsStr.charCodeAt(i) - 48;
    cells[i] = v;
    if (v !== 0) countFilled++;
  }
  return { id, source, indexInFile, cells, countFilled, difficulty: DIFF_BY_SOURCE[source] ?? 'medium' };
}

export function getPuzzleById(id: string): NumplePuzzle | null {
  const cached = parsedCache.get(id);
  if (cached) return cached;
  const hit = RAW.find(([pid]) => pid === id);
  if (!hit) return null;
  const p = build(hit[0], hit[1]);
  parsedCache.set(id, p);
  return p;
}

export function getPuzzlesByDifficulty(difficulty: Difficulty, limit = 50): NumplePuzzle[] {
  const out: NumplePuzzle[] = [];
  for (const [id] of RAW) {
    if (DIFF_BY_SOURCE[id.slice(0, id.lastIndexOf('_'))] !== difficulty) continue;
    out.push(getPuzzleById(id)!);
    if (out.length >= limit) break;
  }
  return out;
}

export function getRandomPuzzle(difficulty?: Difficulty): NumplePuzzle | null {
  if (RAW.length === 0) return null;
  if (difficulty) {
    const pool: string[] = [];
    for (const [id] of RAW) {
      if (DIFF_BY_SOURCE[id.slice(0, id.lastIndexOf('_'))] === difficulty) pool.push(id);
    }
    if (pool.length === 0) return null;
    return getPuzzleById(pool[Math.floor(Math.random() * pool.length)]);
  }
  const pick = RAW[Math.floor(Math.random() * RAW.length)];
  return getPuzzleById(pick[0]);
}

export function getDailyPuzzle(): NumplePuzzle | null {
  if (RAW.length === 0) return null;
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = (now.getTime() - start.getTime()) / 86400000;
  const dayIdx = Math.floor(diff) % RAW.length;
  return getPuzzleById(RAW[dayIdx][0]);
}

export function puzzleCount(): number {
  return RAW.length;
}

export function difficultyStats(): Record<Difficulty, number> {
  const out: Record<Difficulty, number> = { easy: 0, medium: 0, hard: 0, expert: 0 };
  for (const [id] of RAW) {
    out[DIFF_BY_SOURCE[id.slice(0, id.lastIndexOf('_'))] ?? 'medium']++;
  }
  return out;
}

/** Convert flat cells[] (length 81) to 9x9 grid for solver/board. */
export function cellsToGrid(cells: Value[]): Grid {
  const grid: Grid = [];
  for (let r = 0; r < 9; r++) {
    grid.push(cells.slice(r * 9, (r + 1) * 9));
  }
  return grid;
}

/** Get solution lazily via SudokuSolver. */
export function solvePuzzle(p: NumplePuzzle): Grid | null {
  return solveCached(p.id, cellsToGrid(p.cells));
}
